globalThis.__IT_TREND_EMBEDDED_DATA__ = {"updated_at":"2026-11-17 21:35:15 JST","total_count":50,"config":{"selected_genres":["ai","web","infra","mobile","biz"],"other_genre_min_ratio":0.25,"max_age_hours":72,"genres":{"ai":"AI・LLM・機械学習","web":"Web開発・言語","infra":"インフラ・クラウド・セキュリティ","mobile":"モバイル・ガジェット・個人開発","biz":"ITビジネス・キャリア・マネジメント","other":"総合・その他IT"}},"articles":[{"title":"楽天証券に不正アクセス、最大1125万口座のIDなど漏えいか　最大447万口座は金融資産情報も","url":"https://www.itmedia.co.jp/news/article/2611/17/2000003275/","source":"Hatena","published_at":"2026-11-17 19:45","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"楽天証券で不正アクセス発生、最大1125万口座の個人情報漏えいの恐れ","summary":"楽天証券は11月17日、第三者による不正アクセスにより、最大約1125万口座分の顧客情報が漏えいした可能性があると発表しました。うち約447万口座については、氏名、住所、金融資産情報なども含まれる可能性があります。\n\n原因はテスト環境のシステム管理不備と見られ、現在詳細を調査中です。なお、ログインパスワードや暗証番号の漏えいは確認されておらず、不正取引も現時点では報告されていません。同社は対象顧客への個別連絡と、パスキー認証の利用を推奨しています。","importance":10},{"title":"NVIDIA、CEO 交代に関するお知らせ","url":"https://blogs.nvidia.co.jp/blog/nvidia-announces-ceo-transition/","source":"Hatena","published_at":"2026-11-17 15:39","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"NVIDIAのジェンスン・フアンCEOが辞任、暫定CEOにコレット・クレスCFOが就任","summary":"NVIDIAのジェンスン・フアン氏が社長兼CEO、取締役を即時辞任したことが発表されました。後任の正式なCEOが決定するまで、現CFOのコレット・クレス氏が暫定CEOを務めます。\n\nまた、同社初の取締役会議長としてハーベイ・ジョーンズ氏が任命されました。AI業界の巨人であるNVIDIAのトップ交代は、今後の半導体市場やAI戦略に大きな影響を与える可能性があり、業界内外から注目を集めています。","importance":10},{"title":"ローカルLLM入門","url":"https://zenn.dev/port_inc/articles/ff974c7456f4db","source":"Zenn","published_at":"2026-11-17 16:17","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"ローカルLLMの仕組みと推論速度を左右するメモリ帯域の重要性","summary":"ローカル環境でLLMを動かすための基礎知識と技術的背景を解説。モデルの正体である「重み」の扱い方から、推論エンジン（llama.cpp等）の仕組みまでを整理しています。\n\n特に推論速度については、計算性能よりもメモリ帯域がボトルネックになることを指摘。最新のハードウェア（Apple Mシリーズ等）における推論の挙動や、オープンモデルとクローズドモデルの性能差の縮小傾向など、実用的な視点からローカルLLMの現在地を紐解いています。","importance":8},{"title":"位置情報「流出」のルート　売買されるあなたの居場所","url":"https://vdata.nikkei.com/newsgraphics/location-data-leaks-route/","source":"Hatena","published_at":"2026-11-17 03:59","genre":"other","genre_label":"総合・その他IT","headline":"スマホアプリから海外へ流出する位置情報の流通ルート","summary":"スマートフォンの位置情報がアプリ内のSDKを通じて収集され、海外のデータブローカーを通じて売買されている実態を追ったレポートです。人流解析や広告配信の名目で収集されたデータが、個人の行動履歴として不透明なルートで流通しています。\n\n業界団体は利用者の同意があれば海外流出も起こり得ると指摘していますが、流通の全容把握は困難です。アプリ開発におけるSDKの選定や、プライバシーポリシーの透明性が改めて問われています。","importance":7},{"title":"おい、 Mutation Test をやれ。テスト品質を、測るために","url":"https://zenn.dev/mizchi/articles/mutation-test-quality","source":"Hatena","published_at":"2026-11-17 18:59","genre":"web","genre_label":"Web開発・言語","headline":"AI時代のテスト品質担保に「ミューテーションテスト」の導入を推奨","summary":"AIによるコード生成が普及し、テストカバレッジを上げることは容易になりましたが、そのテストが本当に品質を担保しているかは別問題です。単純な分岐カバレッジの限界に対し、ソースコードを意図的に書き換えてテストの有効性を測る「ミューテーションテスト」の有用性が説かれています。\n\nミューテーションテストは、コードの比較演算子などを書き換えた「ミュータント」を作成し、テストがそれを検知できるかを確認する手法です。これにより、テストコード自体の品質を保証し、AIが生成したコードに対する信頼性を高めることができます。","importance":7},{"title":"メルカリ、Google Play ストアでアプリが検索・ダウンロードできない状態に","url":"https://www.itmedia.co.jp/news/article/2611/17/2000003274/","source":"Hatena","published_at":"2026-11-17 19:58","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"メルカリがGoogle Playストアから一時的に検索・ダウンロード不可に","summary":"11月17日夕方、Google Playストアにてフリマアプリ「メルカリ」が検索・ダウンロードできない障害が発生しました。Webブラウザからアクセスしても「URLが見つからない」と表示される状態となり、メルカリ社は原因を調査中としています。\n\nユーザーに対しては、既存アプリを削除しないよう呼びかけが行われました。突如として主要アプリがストアから消失する事態に、SNS等でも大きな注目が集まりました。","importance":6},{"title":"楽天証券に不正アクセス、最大1125万口座のログインIDなど漏えいのおそれ","url":"https://japan.cnet.com/article/35255023/","source":"Hatena","published_at":"2026-11-17 18:54","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"楽天証券で不正アクセス、最大1125万口座の情報漏えいのおそれ","summary":"楽天証券において第三者による不正アクセスが発生し、最大約1125万口座のログインIDなどが漏えいした可能性があると発表。テスト環境で管理されていた情報が外部に流出したとみられる。\n\n氏名、住所、出金先口座情報などを含む最大約447万口座の情報も対象。パスワードや暗証番号の漏えいは確認されていないが、同社はパスキー認証の設定を強く推奨している。","importance":10},{"title":"Go Conference 2026実行委員を終えて","url":"https://zenn.dev/mire0726/articles/1f3f118662a0f5","source":"Zenn","published_at":"2026-11-17 16:21","genre":"other","genre_label":"総合・その他IT","headline":"Go Conference 2026運営の振り返りと次世代へのバトン","summary":"Go Conference 2026の運営を終えた実行委員による振り返り記事です。持続可能なカンファレンス作りを目指し、プロジェクト制度の導入や学生支援、プロポーザル採択基準の一新など、多くの挑戦が行われました。\n\nAI時代におけるセッションのあり方や、Discordを活用したスタッフ間のコミュニケーション活性化など、運営の知見が共有されています。2027年の実行委員長への交代も発表され、コミュニティの持続的な発展に向けた熱意が綴られています。","importance":5},{"title":"AI時代の生産性を考える","url":"https://zenn.dev/mediaforce/articles/b7075a9e04e871","source":"Zenn","published_at":"2026-11-17 16:12","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"AI時代の生産性は「速くやる」ことではなく「提供価値を増幅する」こと","summary":"AIを活用した生産性向上について、単なる作業時間の短縮ではなく「これまでやらなかったことをやる」という視点の転換を提唱しています。AIを魔法のツールではなく、提供価値を増幅させる装置と捉えるべきだと説きます。\n\n想定QAの先出しや、ヒアリング段階でのデザイン提示など、AIを活用して期待値を超えるアウトプットを出す手法を紹介。AIから出てくる回答を自分の言葉で説明できるレベルまで昇華させることの重要性を強調しています。","importance":7},{"title":"エージェントの自律性を上げると、何が得られて何を失うか —— 助言・承認付き実行・自律実行を実測する","url":"https://zenn.dev/enterprise_ai/articles/1b1f34af88fb8f","source":"Zenn","published_at":"2026-11-17 15:51","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AIエージェントの自律性とガバナンス：承認プロセスはどこまで有効か","summary":"AIエージェントの自律性を「助言」「承認付き実行」「自律実行」のレベルで比較検証した実測レポートです。承認プロセスを導入しても、誤った方針や信じ込みは止められないという課題が浮き彫りになりました。\n\n結論として、操作の審査は人ではなく仕組み（フックやモデルによる審査）に任せるべきであり、承認の負担は回数ではなく「読む量」で見積もるべきだと提言。Gartnerが提唱する「比例的ガバナンス」に基づき、自律レベルに応じた統制の重要性を説いています。","importance":8},{"title":"Firestoreルールの「ログイン済みなら誰でも read」が招待を全部漏らす話","url":"https://zenn.dev/crs/articles/01-firestore-rules-enumeration","source":"Zenn","published_at":"2026-11-17 12:36","genre":"web","genre_label":"Web開発・言語","headline":"Firestoreルールの「read」権限設定におけるセキュリティリスク","summary":"Firestoreルールで「ログイン済みなら誰でもread可能」と設定すると、list（一覧取得）も許可されてしまい、招待トークンや全ユーザー情報が漏えいするリスクがあります。本記事では、この高リスクな穴を塞ぐための具体的な修正手順を解説しています。\n\n対策として、readをgetに絞り一覧取得を禁止すること、トランザクションとgetAfter()を用いて招待の使用済み化を強制すること、usersコレクションへの書き込みを許可リスト化することなどを実施。ルールはエミュレータでテストし、実装の都合で緩めた権限が残らないよう注意が必要です。","importance":8},{"title":"LTを盛り上げよう！AWSサービス応援うちわ制作裏話","url":"https://zenn.dev/namiki64/articles/7aab23e02d1dc4","source":"Zenn","published_at":"2026-11-17 12:55","genre":"other","genre_label":"総合・その他IT","headline":"AWSサービスを推す！LTイベント用「応援うちわ」制作の裏側","summary":"JAWS-UG大阪のLTイベントにて、アイドル文化を模した「推しサービス応援うちわ」を制作した事例です。AIを活用して各サービスの特徴を捉えたキャッチーなフレーズを生成し、デザインの多様性を確保しながら制作しました。\n\n制作プロセスでは、まず対象サービスの特徴を固め、AIにフレーズ案を依頼し、人力でアクセントを加える手法をとりました。単なる技術発表に留まらず、視覚的な演出を加えることでイベントの盛り上げを図る試みは、コミュニティ運営における新しいアプローチとして参考になります。","importance":4},{"title":"GlobalProtectが切れたらWSLから再接続するPowerShellスクリプト（On-demand環境向け）","url":"https://zenn.dev/acntechjp/articles/9cdae8904dabb7","source":"Zenn","published_at":"2026-11-17 16:02","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"GlobalProtectの接続を自動化するWSL向けPowerShellスクリプト","summary":"Windows版GlobalProtectの接続ボタンをPowerShellから操作し、WSL環境からVPN接続を制御する自作スクリプトの紹介です。公式CLIが利用できない環境において、UI Automationを用いて接続状態を判定し、自動再接続を実現します。\n\n仮想アダプタの監視や座標クリックによるボタン操作など、環境依存を考慮した実装が特徴。VPNが切断された際に自動で復旧させることで、開発環境の利便性を向上させる実用的なハックです。","importance":5},{"title":"楽天証券に不正アクセス、最大1125万口座のログインIDなど漏えいのおそれ（CNET Japan） - Yahoo!ニュース","url":"https://news.yahoo.co.jp/articles/141fe69b0f33952604cde710494bbdff584f269a","source":"Hatena","published_at":"2026-11-17 18:33","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"楽天証券の不正アクセス事案：漏えい情報の詳細と対策","summary":"楽天証券の不正アクセス事案に関する続報。最大1125万口座のログインIDに加え、氏名や住所、年収、金融資産情報などが漏えいした可能性があることを報じている。\n\n退会者の情報も含まれており、影響範囲は広範囲に及ぶ。同社は影響を受けた顧客への個別連絡を進めるとともに、不審な連絡への注意喚起と、セキュリティ強化のためのパスキー認証設定を呼びかけている。","importance":10},{"title":"お問い合わせの8割を、AIボットが解決するようになった話","url":"https://zenn.dev/rimo/articles/701d18b7764669","source":"Zenn","published_at":"2026-11-17 10:05","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"Rimoが内製AIボットで問い合わせの8割を自動解決","summary":"Rimoがカスタマーサポートの負荷軽減を目的に、内製のお問い合わせボットを開発し、問い合わせの8割を自動解決するに至った事例です。ヘルプ記事を検索するRAGに加え、契約プランとの照合や過去の問い合わせ要約を参照する仕組みを導入しました。\n\n特筆すべきは、ユーザーのノート処理状況を直接確認し、必要に応じて再実行まで行う踏み込んだ支援です。内製化により、他のAI機能と改善サイクルを共有でき、コストを抑えつつ柔軟な運用が可能になりました。CSアシストボットで先行検証し、顧客向けに展開した段階的なアプローチも成功要因です。","importance":8},{"title":"毎月6,000 AI Agentsを捌くためにキーボードを捨てた話","url":"https://zenn.dev/andoshin11/articles/ba68b39ef9a8ce","source":"Hatena","published_at":"2026-11-17 15:39","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"月6000セッションを捌くAIエージェント開発環境の構築術","summary":"月間6000セッションものAIエージェントを運用する開発環境の構築事例です。認知負荷と意思決定コストを極限まで減らすため、Orca ADEやClaude Codeを活用し、ワンタップで指示を出せる環境を構築しています。\n\nタスク進捗の可視化や、AIからの質問（AskUserQuestion）の自動検知・構造化など、ログを読み解くコストを排除する工夫が満載。AIを自走させるためのプロンプト設計や、開発velocityを最大化するためのマネジメント手法が共有されています。","importance":8},{"title":"AIを活用したPerlのGo移植（テスト編） - Mirrativ Tech Blog","url":"https://tech.mirrativ.stream/entry/2026/11/17/100000","source":"Hatena","published_at":"2026-11-17 10:52","genre":"web","genre_label":"Web開発・言語","headline":"Claude Codeを活用したPerlからGoへのE2Eテスト移植","summary":"ミラティブが実施した、PerlからGoへのバックエンド移植プロジェクトにおけるE2Eテスト移植の事例です。Claude Codeのスキル（t2go）を設計し、約9.5週間で250ファイルのテストをGoへ移植しました。\n\n成功の鍵は、AIに判断させず「計画・実装・レビュー」の役割を明確に分けたスキル設計です。特にレビュー担当には編集権限を与えず、実測値に基づいた指摘をさせることで、AIによる移植の精度を大幅に向上させました。移植漏れや因果関係の誤りといった課題を、AIと人間の協働で解決した実践的な知見です。","importance":8},{"title":"シャープ「AQUOS sense11」発表・26日発売、約157gの薄型ボディに6年セキュリティ更新対応","url":"https://k-tai.watch.impress.co.jp/docs/news/2154453.html","source":"Hatena","published_at":"2026-11-17 15:33","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"シャープ「AQUOS sense11」発表、6年間のセキュリティ更新に対応","summary":"シャープの新型スマートフォン「AQUOS sense11」が発表されました。約157gの軽量薄型ボディに5000mAhの大容量バッテリーを搭載し、6年間のセキュリティアップデートと最大4回のOSバージョンアップを保証しています。\n\nオンデバイスAIを活用したカメラ機能や、統合AIサービス「NIAH」のプリインストールなど、AI機能を強化。Snapdragon 7s Gen 3を搭載し、実用性と長期利用を両立させたミドルレンジモデルとして展開されます。","importance":6},{"title":"楽天証券に不正アクセス 最大1125万口座の情報漏えい可能性","url":"https://www.watch.impress.co.jp/docs/news/2157207.html","source":"Hatena","published_at":"2026-11-17 18:23","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"楽天証券、不正アクセスにより最大1125万口座の情報漏えい可能性","summary":"楽天証券が第三者による不正アクセスを受け、顧客情報が漏えいした可能性があると発表した件の概要。テスト環境のシステムから情報が流出したとされ、ログインIDや個人情報が対象となっている。\n\n取引に必要なパスワードや暗証番号の漏えいは確認されていない。同社は原因究明を継続しつつ、フィッシング詐欺対策としてパスキー認証の利用を顧客に強く促している。","importance":10},{"title":"QA生産性を爆上げさせるためのQA AIプラットフォーム構築","url":"https://zenn.dev/gatechnologies/articles/8bdea59269eb10","source":"Zenn","published_at":"2026-11-16 18:12","genre":"biz","genre_label":"ITビジネス・キャリア・マネジメント","headline":"QA生産性を向上させるAIプラットフォーム「GAQ」の構築","summary":"QAチームのボトルネックを解消するため、AIエージェントを活用したQAプラットフォーム「GAQ」を構築した事例。テスト計画からレポートまでをAIに任せ、人は判断に集中するワークフローを導入した。\n\n12個のSkillを実装し、成果物をMarkdownでGitHubに集約することで、属人化の解消と品質の標準化を実現。AI導入の意義をチームに浸透させ続けるマネジメント手法も併せて紹介している。","importance":8},{"title":"ChatGPTやClaudeがMacを操作する時代に--Appleが「macOS 27.3」で対応強化","url":"https://japan.cnet.com/article/35254992/","source":"Hatena","published_at":"2026-11-17 14:32","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"macOS 27.3でAIエージェントの操作権限管理が強化","summary":"Appleは「macOS 27.3」ベータ2にて、AIエージェントがMacを操作する際の権限管理を厳格化しました。AIの自律的な操作による意図しないデータアクセスやアプリ操作のリスクを低減するため、権限付与の細分化と許可プロセスの透明化を図ります。\n\n具体的には、従来の「フルディスクアクセス」等を「System & App Protection Override」と「アクセシビリティ」に分割し、アプリごとの操作状況を明示する表示機能を追加。AIエージェントだけでなく一般アプリにも適用され、ユーザーが意図した範囲内でのみ操作を許可できる仕組みへと刷新されます。","importance":9},{"title":"Storageルールが参照できるFirestoreドキュメントは2件まで：共有設定を「原子的に」切り替える設計","url":"https://zenn.dev/crs/articles/02-storage-rules-two-docs-limit","source":"Zenn","published_at":"2026-11-17 12:36","genre":"web","genre_label":"Web開発・言語","headline":"Firestoreの参照制限を回避するStorageルール設計","summary":"Firebase Storageのセキュリティルールにおいて、1回の評価で参照できるFirestoreドキュメントは2件までという制限があります。写真の共有設定を管理する際、この制限に抵触しないための設計変更の記録です。\n\n当初はスポットごとに共有設定を持たせていましたが、更新の原子性が保てず失敗しました。最終的に、連携ドキュメントに共有設定を集約させることで、スポットの件数に依存せず1回の書き込みで整合性を保つ設計を採用。ルールでgetAfter()を活用し、設定の一致を強制することで安全なアクセス制御を実現しました。","importance":7},{"title":"Google日本語入力が不満な人へ、Windows/Mac対応国産ソフト「もずきー」登場。遅延付きライブ変換とAI文脈補正を搭載、使うほど学習し自分好みに（生成AIクローズアップ） | テクノエッジ TechnoEdge","url":"https://www.techno-edge.net/article/2026/11/17/5737.html","source":"Hatena","published_at":"2026-11-17 09:51","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"AI文脈補正とライブ変換を備えた日本語入力ソフト「Mozkey」","summary":"「Mozkey」は、Google日本語入力のオープンソース版「Mozc」をベースにした、Windows/Mac対応の日本語入力ソフトです。遅延付きライブ変換と、ローカルAI「Zenz」による文脈補正を組み合わせ、入力中の文章の流れを読み取って自然な変換を実現します。\n\nローカルファースト設計により、AI処理はPC内部で完結し、外部通信を行わないプライバシー重視の構成となっています。学習機能によりユーザーの書き方に馴染むほか、誤変換の自動取り消し機能も備えており、実用性の高い日本語入力環境を提供します。","importance":6},{"title":"楽天証券が不正アクセスを受け最大約1125万口座分のログインIDなどが漏えい、さらにエンジニア3日の人でもヤバいと分かる行為をやっていたことが判明","url":"https://togetter.com/li/2771595","source":"Hatena","published_at":"2026-11-17 19:31","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"楽天証券の個人情報流出、テスト環境への本番データ混入が批判の的に","summary":"楽天証券の不正アクセスによる大規模な個人情報漏えい事案において、テスト環境に本番データがそのまま置かれていたことが判明し、エンジニア界隈で大きな波紋を呼んでいます。\n\nセキュリティの鉄則である「テスト環境での本番データ利用禁止・マスキング処理」が守られていなかった可能性が高く、企業のガバナンスやセキュリティ意識の欠如が厳しく批判されています。単なるシステム障害を超え、開発プロセスの根本的な不備が露呈した形です。","importance":9},{"title":"AIに打ち明けた相談は“広告トラッカー”に筒抜け？　ChatGPT、Claude、Gemini含む42サービスを米大が調査","url":"https://www.itmedia.co.jp/news/article/2611/17/2000003241/","source":"Hatena","published_at":"2026-11-17 12:01","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AIチャットの会話内容が広告トラッカーへ漏えいする実態","summary":"米ニューヨーク州立大学の研究チームが、42種のAIチャットサービスを調査した結果、会話内容や個人情報が広告トラッカーを通じて外部企業へ漏えいしている実態が明らかになりました。多くのサービスで、会話の要約タイトルやプロンプト本文が機械的に外部へ送信されています。\n\n原因は、Webサイトのタイトル自動取得機能をそのままAIチャットに流用している点にあります。汎用AIの約22％の通信がトラッカー向けであり、GoogleやMicrosoftなどへデータが流れていることが判明。ユーザーはプライベートな対話と期待していても、Webの仕組み上は広告サイトと同等の追跡が行われている現状が浮き彫りになりました。","importance":9},{"title":"Claude Code のタブ同士の受け渡しを、貼り付けから「受信箱＋合図」に変えている途中の記録","url":"https://zenn.dev/hiroxasobiba/articles/agent-tabs-inbox-and-signal","source":"Zenn","published_at":"2026-11-17 12:31","genre":"web","genre_label":"Web開発・言語","headline":"Claude Codeのタブ間連携を「受信箱」方式へ刷新","summary":"複数のClaude Codeを並行稼働させる環境において、タブ間の依頼受け渡しを従来の「貼り付け」から「受信箱（ファイル）＋合図」方式へ移行する取り組みです。貼り付け方式では到達確認が困難で、生成中に本文が消えるリスクがあったため、永続的な受信箱を正とする設計に変更しました。\n\n受信箱にイベントを書き込み、タブには「合図」のみを送ることで、ワーカーが落ちても再開可能な堅牢な仕組みを構築。本番環境への切り替えは段階的に行い、既存の仕組みと並行稼働させて検証を進めることで、開発の安定性を担保しています。","importance":7},{"title":"スマホ内蔵のセンサーを使って周辺光取得を試す","url":"https://zenn.dev/aldagram_tech/articles/f7b57935e31070","source":"Zenn","published_at":"2026-11-17 09:37","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"スマホの周辺光センサー活用：AndroidとiOSでの実装アプローチ","summary":"スマホの周辺光センサーを利用してユーザー体験を向上させるための実装調査記事です。Androidでは標準のSensorManager（TYPE_LIGHT）でルクス単位の取得が可能ですが、iOSでは直接的なセンサーアクセスが制限されているため、ARKitの光推定機能を用いた代替案が現実的です。\n\niOSとAndroidで取得単位や仕組みが異なるため、共通コードで表示ロジックを管理しつつ、OSごとの値取得処理を分離する設計が推奨されます。バックグラウンドでの取得にはプライバシー上の配慮が必要ですが、画面表示中の利用であれば権限申請なしで実装可能です。","importance":5},{"title":"当社お客様の情報漏えいの可能性に関するお詫びとお知らせ:楽天証券","url":"https://www.rakuten-sec.co.jp/web/info/info20261117-02.html","source":"Hatena","published_at":"2026-11-17 17:41","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"楽天証券が不正アクセスによる情報漏えい可能性を公式に謝罪","summary":"楽天証券は、第三者による不正アクセスにより顧客情報が漏えいした可能性があることを公式に発表しました。テスト環境のシステムから情報が流出した可能性が高く、最大1125万口座のIDなどが対象となっています。\n\n同社はパスワードや暗証番号の漏えいは否定しつつも、影響を受けた顧客への個別連絡を開始しています。また、フィッシング詐欺への注意喚起を行うとともに、セキュリティ対策としてパスキー認証の必須化を強く推奨しています。","importance":9},{"title":"AI駆動開発で自分用の情報収集Discordサーバーを作る","url":"https://zenn.dev/tree_and_tree/articles/ai-driven-discord-info-server","source":"Zenn","published_at":"2026-11-17 00:14","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AI駆動開発で構築する個人用情報収集Discordサーバー","summary":"2ヶ月間で500件以上のイシューを起票し、AI駆動開発で個人用情報収集サーバーを構築した事例。Claude CodeとGitHubを連携させ、AIが開発の大部分を担うイシュードリブンな開発スタイルを確立した。\n\n情報収集の自動化だけでなく、開発プロセス自体をAIに最適化させることで、個人の生産性を飛躍的に向上させている。ハーネス改善と配信改善という役割分担や、無料枠を駆使したインフラ構成など、個人開発におけるAI活用の実践的な知見が詰まっている。","importance":9},{"title":"AIが時代遅れのWebサイトを書くのを防ぐスキル「Modern Web Guidance」が安定版に／「Edge」「Firefox」も参加、Webサイトのモダナイズにも","url":"https://forest.watch.impress.co.jp/docs/news/2156904.html","source":"Hatena","published_at":"2026-11-17 10:04","genre":"web","genre_label":"Web開発・言語","headline":"AIのWeb開発を最新化する「Modern Web Guidance」v1.0","summary":"Googleがリリースした「Modern Web Guidance」v1.0は、AIコーディングエージェントに最新のWeb開発手法やブラウザ互換性の知識を与えるスキル集です。AIが生成するコードのアクセシビリティや性能を向上させ、最新のHTML/CSSへのモダナイズを支援します。\n\nv1.0ではChromeに加えEdgeやFirefoxも参加し、クロスブラウザ対応を強化。既存コードの解析から改善提案までを行うワークフローが追加されました。主要なコーディングエージェントのプラグインとして導入可能で、Chrome DevTools for agentsとの併用により、効率的なWeb開発環境を提供します。","importance":7},{"title":"expo-widgetsがiOS 27の新しいウィジェットサイズに対応していなかったので、PRを出してみた","url":"https://zenn.dev/haruzou_tech/articles/expo-widgets-ios27-extra-large-portrait","source":"Zenn","published_at":"2026-11-17 08:47","genre":"mobile","genre_label":"モバイル・ガジェット・個人開発","headline":"Expo WidgetsのiOS 27新サイズ対応PRがマージされるまでの経緯","summary":"iOS 27で追加されたウィジェットサイズ「systemExtraLargePortrait」にExpo Widgetsが未対応だったため、自らPRを作成してマージに至った経験談です。古いiOSバージョンでもビルドが通るよう、OSバージョンチェックを導入する設計がポイントとなりました。\n\nオープンソースプロジェクトへの貢献において、テストコードの追加やレビュー指摘への対応を通じて、コードの品質を高めるプロセスが詳細に記されています。Issueを待つだけでなく、自ら課題を見つけて解決策を提示する重要性が示されています。","importance":4},{"title":"Zoom・CNN・BBC・IKEAなど178組織のサイトにOptimizely経由で悪意のあるJavaScriptが配信され仮想通貨の盗難被害も発生","url":"https://gigazine.net/news/20261117-infect-malware-optimizely/","source":"Hatena","published_at":"2026-11-17 16:13","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Optimizely経由で178組織のサイトに悪意あるJSが混入","summary":"A/Bテストツール「Optimizely」が攻撃を受け、ZoomやBBCなど178組織のウェブサイトに悪意のあるJavaScriptが配信される事態が発生しました。このコードは仮想通貨の盗難やクレジットカード情報の窃取を行うもので、実際に被害も確認されています。\n\n攻撃者はOptimizelyの「Project JavaScript」機能を悪用し、正規のサーバーからマルウェアを配信していました。Content Security Policy (CSP) を適切に設定していた組織では被害が防がれており、サードパーティ製スクリプトの管理とセキュリティ対策の重要性が改めて浮き彫りとなりました。","importance":9},{"title":"MCP Apps・Skills 入門：Ruby の mcp gem で、UI と Skill を配る MCP サーバーを作る","url":"https://zenn.dev/4geru/articles/hokuriku-rubykaigi-02-mcp-apps","source":"Zenn","published_at":"2026-11-17 01:27","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"Rubyのmcp gemでClaudeのUIとSkillを拡張するMCPサーバー開発","summary":"Model Context Protocol（MCP）を活用し、Claudeの会話内に動的なUI（小窓）を表示するMCPサーバーの開発手法を解説しています。Rubyの公式SDK（mcp gem）を使用し、ツール呼び出しの結果をJSONで返し、それをHTMLで描画する仕組みです。\n\nMCP Appsを用いることで、チャット画面内に独自のUIを組み込み、よりリッチなユーザー体験を提供可能です。AIがツールを選択し、ホストが通信を仲介するというアーキテクチャを理解することで、LLMの機能を拡張する新しいアプリケーション開発が可能になります。","importance":8},{"title":"OpenVessel | ブラウザの中で動く、小さな仮想マシン（Node.js・オープンソース・Apache-2.0）| 神戸ソフト","url":"https://kobesoft.co.jp/oss/openvessel/","source":"Hatena","published_at":"2026-11-17 08:27","genre":"web","genre_label":"Web開発・言語","headline":"ブラウザ内でNode.jsを動かす仮想マシン「OpenVessel」","summary":"OpenVesselは、ブラウザのタブ内でNode.jsとnpmを動作させるオープンソースの仮想マシンです。PCへの環境構築なしで、URLを開くだけで開発サーバーの起動やビルドが可能になり、研修や検証環境の共有に最適です。\n\nネイティブモジュールをWebAssembly化することでOS依存を排除し、ブラウザ環境での一貫した開発体験を提供します。商用製品への組み込みも可能なApache-2.0ライセンスであり、オンラインエディタやAIツール開発における強力な基盤となります。","importance":7},{"title":"Google Project Zero、脆弱性の開示期限を段階的に30日へ短縮／AIで発見・悪用が高速化、パッチ展開の猶予や大半の特例を廃止","url":"https://forest.watch.impress.co.jp/docs/news/2156900.html","source":"Hatena","published_at":"2026-11-17 14:08","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Google Project Zero、脆弱性開示期限を30日へ短縮","summary":"Googleの脆弱性調査チーム「Project Zero」は、脆弱性の情報開示ポリシーを「Full X」へ改定しました。AIの活用により脆弱性の発見・悪用スピードが加速している現状を鑑み、ベンダーへの修正猶予期間を段階的に短縮し、最終的に報告から30日での開示を目指します。\n\n2027年2月には60日、2028年1月には30日へと短縮され、従来の「ソークタイム（パッチ展開猶予）」などの特例も廃止されます。深刻度に関わらず一律の期限を設けることで、パッチギャップを最小化し、ユーザーを迅速に保護する狙いがあります。","importance":9},{"title":"最近、コードを真面目に読まなくなった","url":"https://zenn.dev/hiromoo/articles/reading-less-preparing-more","source":"Zenn","published_at":"2026-11-17 00:24","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AI時代のコードレビュー：精読から前提設計へのシフト","summary":"AIが生成するコードの精度向上に伴い、すべての差分を精読する習慣を見直すべきという考察。AIを単なるコード生成ツールではなく、推論能力を持つパートナーとして捉え、実装そのものよりも「何を改善したいか」「守るべき条件は何か」という前提条件の設計に注力すべきと説く。\n\nAIの推測能力を活かしつつ、期待値とのズレを防ぐためのコンテキスト共有が重要。AIの能力を認めることで、エンジニアの仕事の幅を広げられる可能性を示唆している。","importance":8},{"title":"Critical脆弱性があるのにnpm auditには出なかった","url":"https://zenn.dev/billysama/articles/d73b80972c9d67","source":"Zenn","published_at":"2026-11-17 00:26","genre":"web","genre_label":"Web開発・言語","headline":"npm auditに脆弱性が表示されないケースと教訓","summary":"ViteのCriticalな脆弱性がnpm auditに表示されなかった事例を解説。GitHubのリポジトリアドバイザリとグローバルDBへの反映には時差があり、監査ツールが常に最新の全脆弱性を網羅しているわけではないことが判明した。\n\n公式アドバイザリを直接確認し、影響範囲と成立条件を照合する重要性を強調。npm auditの結果を「安全」の根拠にせず、脆弱性情報には常に能動的にアクセスする姿勢が求められる。","importance":7},{"title":"Microsoft 365の大規模障害、原因はサーバーの潜在的なバグ","url":"https://pc.watch.impress.co.jp/docs/news/2157036.html","source":"Hatena","published_at":"2026-11-17 13:51","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Microsoft 365大規模障害、Windowsサーバーのバグが原因","summary":"11月13日に発生したMicrosoft 365の大規模障害は、Windowsサーバーの潜在的なバグと負荷増大が重なったことで引き起こされました。ネットワークゲートウェイのプロセス内でロック競合が発生し、サーバーが応答不能に陥ったことが発端です。\n\n障害は連鎖的に拡大し、世界的なサービス停止へと発展しました。同社は、復旧支援用の容量確保やトラフィック分散ガードレールの実装など、再発防止策を講じています。なお、原因となったバグは7月に展開された修正プログラムに起因するもので、広範なWindows環境には影響しないとのことです。","importance":9},{"title":"LLM に別の LLM の重みを書き換えさせる Weight-Space Programming を、Claude で試してみた","url":"https://zenn.dev/flinters_blog/articles/d0e738719e0054","source":"Zenn","published_at":"2026-11-17 12:00","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"LLMの重みを直接書き換える「Weight-Space Programming」の検証","summary":"MIT CSAILが発表した、LLMの重みを別のLLMに直接書き換えさせる「Weight-Space Programming」を検証したレポートです。学習なしでモデルの振る舞いを変える手法として注目されていますが、実態は思考ループの除去など限定的な効果に留まる可能性も指摘されています。\n\n著者は実際にClaudeを用いてQwenの重みを書き換え、Markdown出力の癖を消す実験を行いました。結果として出力形式は変わったものの、文章の質にも影響が出るなど、モデル編集の難しさが浮き彫りになりました。プロンプトやファインチューニングに続く第3の選択肢として、今後の研究が期待されます。","importance":7},{"title":"「テストが通る」と「守られている」は別 ― AI が書いたテストが、仕様を変えても 24/24 で通った","url":"https://zenn.dev/t_azk/articles/ai-tests-passed-24-of-24","source":"Zenn","published_at":"2026-11-16 22:54","genre":"web","genre_label":"Web開発・言語","headline":"AIが書いたテストの罠：文字列一致による誤検知の教訓","summary":"仕様変更時にテストが「緑」のまま守られていなかった失敗事例を解説。原因は、属性の存在確認を文字列一致で行っていたため、コメント内の案内文にマッチしてしまったことにある。\n\nテストが「通る」ことと「守られている」ことは別物であり、特に生成コードの検証ではReflectionやASTを用いて宣言そのものを検査すべきと結論づける。テストの使いどころと、検査対象の正確な定義の重要性を説く。","importance":7},{"title":"スーパーコンピューター「富岳」への不正アクセスについてまとめてみた - piyolog","url":"https://piyolog.hatenadiary.jp/entry/2026/11/17/030254","source":"Hatena","published_at":"2026-11-17 06:42","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"スパコン「富岳」への不正アクセスと情報漏えいリスクのまとめ","summary":"スーパーコンピューター「富岳」が外部から不正アクセスを受け、運用が停止された事案のまとめです。公開されていたダッシュボードを足がかりに内部ネットワークへ侵入され、利用者情報やSSH秘密鍵などが持ち出された可能性があります。\n\n理化学研究所は全利用者のログイン用公開鍵を無効化し、再発防止策を講じた上での運用再開を目指しています。研究データの流出懸念や、接続先サービスでの認証情報再発行が必要となるなど、影響は広範囲に及んでいます。セキュリティ対策の重要性を再認識させる事例です。","importance":9},{"title":"フロントエンドの logic と UI は、エージェントの責任範囲で分けられるのか","url":"https://zenn.dev/xtm_blog/articles/20261116-fd1702b0ba06cd","source":"Zenn","published_at":"2026-11-17 08:00","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AIエージェント開発におけるフロントエンドとバックエンドの責任分界点","summary":"AIエージェントが自律的に開発を行う基盤において、フロントエンドとバックエンドの工程をどう分けるかという試行錯誤の記録です。全体を通しで実行すると時間がかかりすぎるため工程を分割しましたが、フロントエンドはバックエンドの完成を待たないと評価できないという課題に直面しました。\n\n「各工程は自分で評価できて責任を負えるものだけを持つ」という原則を立て、契約（API定義）を介した疎結合な開発モデルを模索しています。エージェントによる自律開発パイプラインを構築する上で、テストの誤りや原因切り分けをどう自動化するかが今後の鍵となります。","importance":7},{"title":"mise + gh skill で、dotfiles から Agent Skills を管理する","url":"https://zenn.dev/dress_code/articles/30bd78e1a67f87","source":"Zenn","published_at":"2026-11-17 12:00","genre":"web","genre_label":"Web開発・言語","headline":"miseとgh skillを用いたAgent Skillsの効率的な管理手法","summary":"dotfiles管理ツール「mise」を活用し、Claude CodeやCursor用のAgent Skillsを効率的に管理する手法です。以前はスクリプトでファイルを生成していましたが、管理の複雑化を避けるため、skillを別リポジトリに切り出し、miseのタスク機能で一括導入する構成に変更しました。\n\nこれにより、会社固有の規約と公開用設定の分離が容易になり、環境構築の再現性も向上しました。CursorがClaudeのディレクトリも読み込む仕様を活かし、ツールごとの生成スクリプトを廃止。宣言的な管理により、新しいMacへの移行もmakeコマンド1回で完結する環境を実現しています。","importance":6},{"title":"65,535時間で死ぬSSDと死にかけた情シスの話","url":"https://zenn.dev/bellx2/articles/9acdc81630b72b","source":"Zenn","published_at":"2026-11-17 15:14","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"Micron製SSDのファームウェア不具合による大規模障害と対処法","summary":"Micron 5200/5100シリーズにおいて、通電時間65,535時間を超えるとI/Oが極端に遅延するファームウェアの不具合が判明。SMART情報が正常なままストレージが応答不能になるため、ネットワーク障害と誤認しやすい点が特徴です。\n\n本件は劣化ではなく、同時期導入のSSDが一斉にタイマーを踏む現象でした。一時的な電源断では約4時間で再発するため、非公開の修正版ファームウェア（D1MU040）への更新が必須です。運用中の環境では、iostat等でディスクごとの待ち時間（await）を監視し、異常な遅延が発生していないか確認することを推奨します。","importance":8},{"title":"AIバブル崩壊間近な現状、AIが人類を滅ぼせるわけねーだろ - サッとぶ","url":"https://kei-1010.hatenablog.com/entry/2026/11/16/120828","source":"Hatena","published_at":"2026-11-16 21:26","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"AI脅威論への反論：自己進化ループはなぜ不可能か","summary":"AIが人類を滅ぼすという脅威論に対し、技術的・数学的な観点から否定的な見解を示す論考。完全自律の自己進化ループ（RSI）が、計算機科学や物理的な壁により2050年時点でも実現困難であることを主張する。\n\n自律MLOpsの限界、継続学習における破局的忘却、評価軸の自己拡張の不可能性など、AI推進派が挙げる6つの技術要素が抱える矛盾を指摘。AIはあくまで「閉じた領域」で機能する便利なツールであると結論づけている。","importance":7},{"title":"git rebaseをちゃんと理解する","url":"https://zenn.dev/ushi_osushi/articles/understanding-git-rebase","source":"Zenn","published_at":"2026-11-17 08:00","genre":"web","genre_label":"Web開発・言語","headline":"Git rebaseの仕組みと履歴書き換えの正しい理解","summary":"Git rebaseは「履歴を書き換える」コマンドとして敬遠されがちですが、実際には既存のコミットを基に新しいコミットを作り直す操作です。mergeがマージコミットを追加するのに対し、rebaseは履歴を直線的に保つことができます。\n\nrebase実行時にハッシュが変わる理由や、reflogを用いた復旧方法、コンフリクト発生時の対処法を解説しています。rebaseは強力なツールですが、リモートにpush済みのコミットに対して行う場合は注意が必要であり、チーム開発での運用ルールを理解することが不可欠です。","importance":5},{"title":"AWS Emulator触ってみた","url":"https://zenn.dev/nagatoshi/articles/try-aws-emulator","source":"Zenn","published_at":"2026-11-17 07:25","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"ローカルでAWS環境をエミュレートする「AWS Emulator」の検証","summary":"2026年11月に発表された「AWS Emulator」を触ってみた検証記事です。Rustで実装されており、軽量かつAWS SDKと同じモデルで動作するため、ローカルでの開発やテスト環境として高い可能性を秘めています。\n\nDockerコンテナとして実行し、S3やDynamoDB、LambdaなどのリソースをCLI経由で操作可能です。AWS環境を汚さずにテストを並列実行できるため、IaCとの組み合わせやCI/CDパイプラインへの導入が期待されます。","importance":8},{"title":"さくらのAI Engineの全チャットモデルにフランス語の小テスト60問を解かせて比べた","url":"https://zenn.dev/classnow/articles/1e7f0f755ec690","source":"Zenn","published_at":"2026-11-16 20:05","genre":"ai","genre_label":"AI・LLM・機械学習","headline":"さくらのAI Engine全モデルでフランス語小テストを比較","summary":"さくらのAI Engineで提供される7つのモデルに対し、フランス語の文法小テスト60問を解かせて性能を比較検証。コード生成に強いモデルが文法問題でも高い正答率を示すなど、モデルごとの特性を明らかにしている。\n\n1問1リクエストと一括リクエストでの精度変化や、埋め込みモデルの対訳検索性能も検証。語学学習の自動化ツール開発に向けた、実用的なモデル選定の指針となるレポート。","importance":6},{"title":"Kotlin Fest 2026 参加記","url":"https://zenn.dev/0st_ts/articles/d55862e1a134c2","source":"Zenn","published_at":"2026-11-16 19:00","genre":"web","genre_label":"Web開発・言語","headline":"Kotlin Fest 2026参加記：最新機能と設計思想","summary":"Kotlin Fest 2026の参加レポート。Kotlin 2.5.0-RCの実験的機能や、Project Valhallaを見据えた不変性の設計、Dokkaによるドキュメント生成など、言語の進化と設計思想に関する講演内容を振り返る。\n\n学生スカラシップでの参加を通じ、最新の技術動向やコミュニティの熱量に触れた体験を記録。型による間違いの防止や、安全なコードを効率的に書くためのKotlinの設計思想について深い洞察を得ている。","importance":6},{"title":"実践パスキー認証設計","url":"https://zenn.dev/yasuakiomokawa/articles/89f5c46e8effe9","source":"Zenn","published_at":"2026-11-16 21:53","genre":"infra","genre_label":"インフラ・クラウド・セキュリティ","headline":"認証基盤におけるパスキー導入の設計と勘所","summary":"個人開発の認証基盤にパスキーを導入した際の設計記録。実装手法ではなく、要求・要件・やってはいけないことの3層で整理し、後から困らないための設計思想を解説する。\n\nフィッシング対策としてのパスキーの有効性をビジネス側に説明するポイントや、ステートマシンを避け「行の有無」で状態を管理する設計など、認証基盤開発における実践的な知見がまとめられている。","importance":8}]};
